function launchCampSearch(mode='coast'){if(platformGame)platformGame.stop();walkMode=mode;if(shopGame)shopGame.stop();if(campGame)campGame.stop();screen='camp';controls.replaceChildren();controls.classList.remove('map-mode','dragging');if(!walkGames[mode]||journeyActive)walkGames[mode]=window.createCampSearch({canvas:cv,inputSurface:controls,images,drawPanel:panel,drawText:text,announce,mode,objective:journeyActive,completeLabel:journeyActive?'ДАЛЕЕ':'НА КАРТУ',onExit:()=>{if(journeyActive)gameCompleted();else setScreen('map')}});campGame=walkGames[mode];campGame.start();render()}


