function drawMap(){rect(0,0,320,240,'#060c16');clampCamera();ctx.save();ctx.beginPath();ctx.rect(mapView.x,mapView.y,mapView.w,mapView.h);ctx.clip();ctx.drawImage(PeninsulaColors.picture(images.map,'map'),mapView.x-camera.x,mapView.y-camera.y);(ctx.filter=PeninsulaColors.pictureFilter('map'),window.PeninsulaMapWater?.draw(ctx,mapView.x-camera.x,mapView.y-camera.y),ctx.filter='none');for(let i=0;i<points.length;i++){const p=points[i],x=p.x-camera.x+mapView.x,y=p.y-camera.y+mapView.y;if(x<mapView.x+5||x>312-5||y<mapView.y+5||y>207-5)continue;rect(x-3,y-3,7,7,'#060c16');rect(x-2,y-2,5,5,visited.has(i)?'#84b5a7':i===selected?'#f1d39a':'#e44a38');hit(p.full,x-5,y-5,11,11,()=>selectDestination(i));buttons[buttons.length-1].mapPoint=true}ctx.restore();ctx.drawImage(images.map_frame,0,0);ctx.drawImage(images.ornament_left,7,5);ctx.drawImage(images.ornament_right,250,5);panel(5,212,310,24);text(loading?'В ПУТИ…':visited.size===5?'ВСЕ ПЯТЬ ТОЧЕК ПОСЕЩЕНЫ':'КУДА ВЫ ОТПРАВИТЕСЬ?',179,220,8,'#dce5ef','center');button('ГЕРОЙ',9,216,46,15,()=>setScreen('hero'));if(dialog||loading){buttons=[];if(loading){rect(8,8,304,199,'#04091099');panel(35,79,250,98);text('ВЫ ОТПРАВЛЯЕТЕСЬ',160,92,8,'#e4e6e8','center');text(points[selected].destination.toUpperCase(),160,110,8,'#e5c695','center');rect(63,138,194,10,'#34465c');rect(65,140,190,6,'#0b121d');rect(65,140,Math.floor(190*progress),6,'#9cb8d1');text(Math.round(progress*100)+'%',160,155,6,'#bccfe3','center')}else{drawMapQuestion()}}}
function travel(){if(loading)return;loading=true;dialog=false;progress=0;announce(LT('ui.sayGo',{place:points[selected].destination}));let last=performance.now(),elapsed=0;timer=setInterval(()=>{const now=performance.now();if(!window.peninsulaShowPaused?.())elapsed+=now-last;last=now;progress=Math.min(1,elapsed/1800);if(progress===1){clearInterval(timer);if(!journeyStarted)visited.add(selected);loading=false;if(journeyStarted){beginChapter(selected);return;}announce(LT('ui.sayArrived',{place:points[selected].full}));if(selected===4){launchPlatform();return}if(selected===2){launchTeriberkaShop();return}if(selected===0||selected===3){launchFogRace(selected===0?'sredny':'fog');return}}render()},40)}
function render(){if(screen==='embedded')return;document.querySelector('#platform-pad').hidden=screen!=='platform';document.querySelector('#fog-back')?.toggleAttribute('hidden',!['camp','shop','platform'].includes(screen));if(screen==='platform'){controls.replaceChildren();platformGame.render();requestAnimationFrame(snapGameToScreen);return}if(screen==='shop'){controls.replaceChildren();shopGame.render();requestAnimationFrame(snapGameToScreen);return}if(screen==='camp'){controls.replaceChildren();campGame.render();requestAnimationFrame(snapGameToScreen);return}buttons=[];ctx.clearRect(0,0,320,240);if(screen==='title'){drawTitle()}else if(screen==='hero')drawHero();else if(screen==='story'||screen==='question'||screen==='epilogue')drawStory();else if(screen==='exchange')drawExchange();else drawMap();drawGameBorder(ctx);controls.classList.toggle('map-mode',screen==='map'&&!dialog&&!loading);syncHotspots();requestAnimationFrame(snapGameToScreen)}
// Clickable spots over the canvas. They are rebuilt only when the set of buttons changes: a spot replaced
