let hotspotKey='';
function syncHotspots(){const key=JSON.stringify(buttons.map(b=>[b.label,b.x,b.y,b.w,b.h,!!b.mapPoint])),els=controls.children;
 if(key===hotspotKey&&els.length===buttons.length){buttons.forEach((b,i)=>{els[i].onclick=()=>{if(!b.mapPoint)b.fn()}});return}
 hotspotKey=key;controls.replaceChildren();buttons.forEach(b=>{let el=document.createElement('button');el.className='hotspot'+(b.mapPoint?' map-point':'')+(b.w>=320&&b.h>=240?' hotspot-full':'');el.setAttribute('aria-label',b.label);Object.assign(el.style,{left:b.x/3.2+'%',top:b.y/2.4+'%',width:b.w/3.2+'%',height:b.h/2.4+'%'});el.onclick=()=>{if(!b.mapPoint)b.fn();};controls.append(el)})}
window.addEventListener('keydown',e=>{if(e.target?.matches?.('input,select,textarea'))return;if(screen==='embedded')return;if(['story','question','epilogue','exchange'].includes(screen)){journeyKey(e);return;}if(screen==='camp'||screen==='shop'||screen==='platform'){if(e.key==='Escape'){e.preventDefault();setScreen('map')}return}if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Enter',' ','Escape','r','R'].includes(e.key)||loading)return;e.preventDefault();if(screen==='title'){if(e.key==='Enter'||e.key===' ')startJourney()}else if(screen==='hero'){if(e.key==='ArrowLeft')changeHero(-1);if(e.key==='ArrowRight')changeHero(1);if(e.key.toLowerCase()==='r'){hero=(hero+1+Math.floor(Math.random()*2))%3;render()}if(e.key==='Enter'){if(journeyStarted)showNode('intro5');else setScreen('map')};if(e.key==='Escape')setScreen('title')}else{if(e.key==='Escape'){if(dialog){dialog=false;render()}else setScreen('hero')}else if(e.key==='Enter'){if(dialog){if(mapChoice){dialog=false;render()}else travel();}else{selectDestination(selected)}}else if(dialog&&e.key.startsWith('Arrow')){mapChoice=1-mapChoice;render()}else if(!dialog&&e.key.startsWith('Arrow')){selected=(selected+(['ArrowLeft','ArrowUp'].includes(e.key)?4:1))%5;revealPoint();render()}}});
let displayScale=2,displayDensityQuery=null;
function snapGameToScreen(){const frame=document.querySelector('#frame'),density=window.devicePixelRatio||1;frame.style.transform='none';frame.style.left='0px';frame.style.top='0px';const bounds=frame.getBoundingClientRect();frame.style.left=((Math.round(bounds.left*density)-bounds.left*density)/density)+'px';frame.style.top=((Math.round(bounds.top*density)-bounds.top*density)/density)+'px';}
function applyDisplayScale(){const density=window.devicePixelRatio||1,frame=document.querySelector('#frame');// ×N means exactly N screen pixels per game pixel, whatever the system display scaling.
frame.style.setProperty('--game-pixel',(displayScale/density)+'px');frame.style.width=(320*displayScale/density)+'px';frame.style.height=(240*displayScale/density)+'px';document.querySelectorAll('[data-scale]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.scale)===displayScale)));requestAnimationFrame(snapGameToScreen)}
function watchDisplayDensity(){if(displayDensityQuery)displayDensityQuery.removeEventListener('change',onDisplayDensityChange);displayDensityQuery=window.matchMedia('(resolution: '+(window.devicePixelRatio||1)+'dppx)');displayDensityQuery.addEventListener('change',onDisplayDensityChange)}
function onDisplayDensityChange(){applyDisplayScale();watchDisplayDensity()}
