window.addEventListener('resize',applyDisplayScale);applyDisplayScale();watchDisplayDensity();
let drag=null;
function mapPointer(e){const bounds=controls.getBoundingClientRect();return {x:(e.clientX-bounds.left)*320/bounds.width,y:(e.clientY-bounds.top)*240/bounds.height}}
controls.addEventListener('pointerdown',e=>{if(screen!=='map'||dialog||loading||e.button!==0)return;const p=mapPointer(e);if(p.x<mapView.x||p.x>=mapView.x+mapView.w||p.y<mapView.y||p.y>=mapView.y+mapView.h)return;drag={id:e.pointerId,startX:p.x,startY:p.y,camX:camera.x,camY:camera.y,x:p.x,y:p.y,moved:false};controls.setPointerCapture(e.pointerId);e.preventDefault()});
controls.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;const p=mapPointer(e);if(Math.hypot(p.x-drag.startX,p.y-drag.startY)>2)drag.moved=true;if(drag.moved){camera.x=drag.camX-(p.x-drag.startX);camera.y=drag.camY-(p.y-drag.startY);clampCamera();controls.classList.add('dragging');render()}drag.x=p.x;drag.y=p.y});
controls.addEventListener('pointerup',e=>{if(!drag||drag.id!==e.pointerId)return;const p=mapPointer(e),wasDrag=drag.moved;drag=null;controls.classList.remove('dragging');if(controls.hasPointerCapture(e.pointerId))controls.releasePointerCapture(e.pointerId);if(!wasDrag){const found=buttons.find(b=>b.mapPoint&&p.x>=b.x&&p.x<b.x+b.w&&p.y>=b.y&&p.y<b.y+b.h);if(found)found.fn()}e.preventDefault()});
controls.addEventListener('pointercancel',()=>{drag=null;controls.classList.remove('dragging')});
