const requestedGame=new URLSearchParams(location.search).get('game');
const oldSetScreen=setScreen;

Promise.all([currentUI.ready,...names.map(n=>new Promise((resolve,reject)=>{let im=new Image;im.onload=()=>{images[n]=im;resolve()};im.onerror=()=>reject(Error(n));im.src='assets/'+assetFiles[n]+'.png?v=20261019-wanderer'}))]).then(()=>{if(requestedGame==='1-1'){journeyStarted=true;journeyActive=true;journeyNode='drive1';launchFogRace('sredny')}else setScreen('title')}).catch(e=>{document.querySelector('#status').textContent='Не удалось загрузить графику. Обновите страницу.'});
